import gurobipy as gp
from gurobipy import GRB

suppliers = ['S1', 'S2', 'S3']
customers = ['C1', 'C2', 'C3', 'C4']
demand = {'C1': 11, 'C2': 1148, 'C3': 54, 'C4': 833}
supply_capacity = {'S1': 4, 'S2': 575, 'S3': 1504}
cost = {'S1': {'C1': 0.63, 'C2': 49.71, 'C3': 33.75, 'C4': 1570.67}, 'S2': {'C1': 605.47, 'C2': 64.53, 'C3': 478.47, 'C4': 887.04}, 'S3': {'C1': 1139.04, 'C2': 4.78, 'C3': 1805.62, 'C4': 1302.89}}

m = gp.Model('Original_RAG_TP')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='x')
m.setObjective(gp.quicksum(cost[i][j] * x[i, j] for i in suppliers for j in customers), GRB.MINIMIZE)
m.addConstrs((gp.quicksum(x[i, j] for i in suppliers) >= demand[j]
              for j in customers), name='demand')
m.addConstrs((gp.quicksum(x[i, j] for j in customers) <= supply_capacity[i]
              for i in suppliers), name='supply')

m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for variable in m.getVars():
        print(f'{variable.VarName}: {variable.X}')
else:
    print(f'Solver status: {m.Status}')



